import{c as s,Q as l,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const n="/assets/AI-CPU%E7%A1%AC%E4%BB%B6%E6%9E%B6%E6%9E%84%E5%9B%BE.CyGzc8Hr.png",g=JSON.parse('{"title":"AI CPU编程","description":"","frontmatter":{},"headers":[{"level":1,"title":"AI CPU编程","slug":"ai-cpu编程"},{"level":2,"title":"AI CPU核函数定义","slug":"ai-cpu核函数定义"},{"level":2,"title":"AI CPU核函数调用","slug":"ai-cpu核函数调用"},{"level":2,"title":"AI CPU模板核函数","slug":"ai-cpu模板核函数"},{"level":2,"title":"更多进阶用法","slug":"更多进阶用法"}],"relativePath":"guide/编程指南/编程模型/AI-CPU编程.md","filePath":"guide/编程指南/编程模型/AI-CPU编程.md"}'),i={name:"guide/编程指南/编程模型/AI-CPU编程.md"};function p(o,a,c,r,_,u){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="ai-cpu编程" tabindex="-1">AI CPU编程 <a class="header-anchor" href="#ai-cpu编程" aria-label="Permalink to &quot;AI CPU编程&quot;">​</a></h1><p>AI CPU是位于Device侧ARM64架构的处理器，其具备与AI Core相同的内存访问能力，可直接访问Device侧内存资源；也可以与Host侧的CPU一样，进行类似的数据计算，通常作为AI Core的补充，主要承担非矩阵类、逻辑比较复杂的分支密集型计算。AI CPU的运行环境为基础的Linux环境，编程时可使用libc库，C++标准库，STL模板库等。其硬件架构图如下所示：</p><p><strong>图 1</strong> AI CPU硬件架构图<br><img src="'+n+`" alt="" title="AI-CPU硬件架构图"></p><p>本节介绍的AI CPU编程仅支持如下产品型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul><h2 id="ai-cpu核函数定义" tabindex="-1">AI CPU核函数定义 <a class="header-anchor" href="#ai-cpu核函数定义" aria-label="Permalink to &quot;AI CPU核函数定义&quot;">​</a></h2><p>在进行AI CPU编程时，与AI Core类似，同样需要定义设备侧函数入口（即核函数），该函数必须通过__aicpu__标识符进行声明，并且需与__global__标识符联合使用以表明其只能被Host侧调用。AI CPU的Device侧实现文件需要以.aicpu为后缀（或者以.cpp为后缀，在编译时增加-x aicpu选项）。该实现文件中包括上面介绍的核函数以及AI CPU普通函数定义，AI CPU普通函数无需添加执行空间标识符。</p><p>如下是一个AI CPU“Hello World”程序的示例，hello_world.aicpu文件内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 调用printf接口需要包含的头文件</span></span>
<span class="line"><span>#include &quot;aicpu_api.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__global__ __aicpu__ uint32_t hello_world(void *args)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::printf(&quot;Hello World!!!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>编程时需要遵循如下规范：</p><ul><li>__aicpu__ __global__函数不能是void返回类型，并且入参只能是一个指针。</li><li>__aicpu__ __global__函数不能是类的成员函数，也不能存在于匿名空间下。</li><li>尽管AI CPU的Kernel函数有返回值，但该返回值仅用于Runtime组件报告运行状态，开发者无需编写返回逻辑，也无法使用该返回值。因此，对于用户而言，AI CPU Kernel函数等同于void类型，不能作为右值使用。</li></ul></div><h2 id="ai-cpu核函数调用" tabindex="-1">AI CPU核函数调用 <a class="header-anchor" href="#ai-cpu核函数调用" aria-label="Permalink to &quot;AI CPU核函数调用&quot;">​</a></h2><p>AI CPU核函数的调用需要在.asc文件中进行，和AI Core的算子调用类似，同样使用&lt;&lt;&lt;&gt;&gt;&gt;语法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello_world&lt;&lt;&lt;numBlocks, nullptr, stream&gt;&gt;&gt;(&amp;args, sizeof(KernelArgs));</span></span></code></pre></div><ul><li>numBlocks：AI CPU Device侧暂不支持分核逻辑，因此Host侧调用多核无实际意义。建议设置为1。</li><li>l2ctrl：保留参数，当前固定为nullptr，开发者无需关注。</li><li>stream：类型为aclrtStream，stream用于维护一些异步操作的执行顺序，确保按照应用程序中的代码调用顺序在Device上执行。stream创建等管理接口请参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi" target="_blank" rel="noreferrer">《Runtime运行时API》</a>。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>在编写调用代码时需要遵循如下规范：</p><ul><li>__aicpu__ __global__函数不能在.asc文件中进行定义，只能声明，且需要使用extern。</li><li>Host侧调用__global__ __aicpu__函数时必须使用&lt;&lt;&lt;&gt;&gt;&gt;异构调用语法，输入的函数入参在入参指针的基础上需要输入从指针中读取的数据大小。</li><li>在Host侧使用内核调用符&lt;&lt;&lt;...&gt;&gt;&gt;调用AI Core与AI CPU算子时不能使用同一条stream。</li></ul></div><p>加载和运行算子时，需要使用Runtime API，完成运行时管理和配置，详细内容请参考<a href="./../编译与运行/异步执行.html">算子运行</a>。AI CPU算子的编译请参考<a href="./../编译与运行/算子编译/AI-CPU算子编译基本用法.html">AI CPU算子编译</a>。</p><h2 id="ai-cpu模板核函数" tabindex="-1">AI CPU模板核函数 <a class="header-anchor" href="#ai-cpu模板核函数" aria-label="Permalink to &quot;AI CPU模板核函数&quot;">​</a></h2><p>若需要使用模板核函数，则需要在.aicpu文件中给出模板核函数的实例化声明，参考如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, int BUFF_SIZE&gt;</span></span>
<span class="line"><span>__global__ __aicpu__ uint32_t hello_world(void *args)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::printf(&quot;Hello World!!!\\n&quot;);</span></span>
<span class="line"><span>    AscendC::printf(&quot;buffer_size is %d\\n&quot;, BUFF_SIZE);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>template __global__ __aicpu__ uint32_t hello_world&lt;KernelArgs, 4096&gt;(void *args);</span></span></code></pre></div><p>并在.asc文件中新增模板核函数实例化的extern声明：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, int BUFF_SIZE&gt;</span></span>
<span class="line"><span>extern __global__ __aicpu__ uint32_t hello_world(void *args);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>template extern __global__ __aicpu__ uint32_t hello_world&lt;KernelArgs, 4096&gt;(void *args);</span></span></code></pre></div><h2 id="更多进阶用法" tabindex="-1">更多进阶用法 <a class="header-anchor" href="#更多进阶用法" aria-label="Permalink to &quot;更多进阶用法&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>更多AI CPU API的使用方法请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AI-CPU-API.md" target="_blank" rel="noreferrer">AI CPU API</a>。</p></div>`,23)])])}const h=s(i,[["render",p]]);export{g as __pageData,h as default};
